            if (orgVerifyCustomDomainDnsSuccessResponse.FlyProvisionErrorOption.IsSet)
                if (orgVerifyCustomDomainDnsSuccessResponse.FlyProvisionErrorOption.Value != null)
                    writer.WriteString("flyProvisionError", orgVerifyCustomDomainDnsSuccessResponse.FlyProvisionError);
                else
                    writer.WriteNull("flyProvisionError");

            if (orgVerifyCustomDomainDnsSuccessResponse.FlyLegacyStaffPipelineOption.IsSet)
                writer.WriteBoolean("flyLegacyStaffPipeline", orgVerifyCustomDomainDnsSuccessResponse.FlyLegacyStaffPipelineOption.Value!.Value);
        }
    }
}
